class Program {
    static void Main() {
        var t = typeof(ResponseError);
        Console.WriteLine("---constructors---");
        foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance))
            Console.WriteLine($"  {c} (public: {c.IsPublic})");
        Console.WriteLine("---converter type---");
        var nested = t.GetNestedType("Converter", BindingFlags.NonPublic | BindingFlags.Public);
        if (nested != null) {
            Console.WriteLine($"  {nested.FullName}");
            Console.WriteLine($"  Has parameterless ctor: {nested.GetConstructor(Type.EmptyTypes) != null}");
            Console.WriteLine($"  IsPublic: {nested.IsPublic}");
        }
    }
}
